#!/usr/bin/env python3
import json,sys
from pathlib import Path
PROJECT="ai-behaviour-control-lab"
FINAL={"PRIMARY_ACCEPTED","PRIMARY_REJECTED"}
def reject(msg): raise ValueError(msg)
def validate(o):
 if o.get("project_id")!=PROJECT: reject("foreign or missing project_id")
 schema=o.get("schema","")
 if schema.endswith("/review/v1"):
  role=o.get("reviewer_role"); ind=o.get("independence"); disp=o.get("disposition")
  if disp in FINAL and (role!="PRIMARY" or ind!="PRIMARY_FINAL"): reject("final disposition requires PRIMARY + PRIMARY_FINAL")
  if ind=="PRIMARY_FINAL" and (role!="PRIMARY" or disp not in FINAL): reject("PRIMARY_FINAL is reserved for Primary final disposition")
  if disp=="READY_FOR_PRIMARY" and role not in {"MANAGER","REVIEWER"}: reject("READY_FOR_PRIMARY requires Manager/Reviewer")
  if role=="RESEARCH" and disp in FINAL|{"READY_FOR_PRIMARY"}: reject("Research cannot promote or accept project truth")
 return True
if __name__=="__main__":
 o=json.loads(Path(sys.argv[1]).read_text()) if len(sys.argv)>1 else json.load(sys.stdin)
 validate(o); print("PASS")
